configuration.tbelDecoder:
/** Decoder **/
var data = decodeToJson(payload);

// Se il messaggio è inserito nel wrapper dell'Integrazione MQTT
var p = (data && data.payload) ? data.payload : (data || {});

// Recupera il nome dal payload o usa sensore_001 di default
var deviceName = p.device_id ? String(p.device_id) : 'sensore_001';
var deviceType = 'Optical Biosensor';

// Sotto-oggetti del biosensore
var hw = p.hw || {};
var analysis = p.analysis || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

var result = {
   deviceName: deviceName,
   deviceType: deviceType,
   attributes: {
       sample_id: p.sample_id || ''
   },
   telemetry: {
       spore_count: Number(analysis.spore_count || 0),
       detected: analysis.detected ? 1 : 0,
       frame_id: Number(p.frame_id || 0),
       cpu_temp_c: Number(hw.cpu_temp_c || 0),
       processing_time_s: Number(hw.processing_time_s || 0),
       ram_used_percent: Number(ram.used_percent || 0),
       disk_used_percent: Number(disk.used_percent || 0),
       
       // Supporto per il test rapido {"prova": true}
       prova: p.prova
   }
};

return result;
